{
  "states": [
    "Not Authenticated",
    "Authenticated",
    "Selected",
    "Logout"
  ],
  "transitions": [
    {
      "from": "Not Authenticated",
      "event": "successful LOGIN or AUTHENTICATE command",
      "action": "",
      "to": "Authenticated"
    },
    {
      "from": "Authenticated",
      "event": "successful SELECT or EXAMINE command",
      "action": "",
      "to": "Selected"
    },
    {
      "from": "Selected",
      "event": "CLOSE or UNSELECT command, unsolicited CLOSED response code, or failed SELECT or EXAMINE command",
      "action": "",
      "to": "Authenticated"
    },
    {
      "from": "Selected",
      "event": "successful SELECT or EXAMINE command",
      "action": "",
      "to": "Selected"
    },
    {
      "from": "Not Authenticated",
      "event": "LOGOUT command, server shutdown, or connection closed",
      "action": "server MUST send an untagged BYE response and a tagged OK response",
      "to": "Logout"
    },
    {
      "from": "Authenticated",
      "event": "LOGOUT command, server shutdown, or connection closed",
      "action": "server MUST send an untagged BYE response and a tagged OK response",
      "to": "Logout"
    },
    {
      "from": "Selected",
      "event": "LOGOUT command, server shutdown, or connection closed",
      "action": "server MUST send an untagged BYE response and a tagged OK response",
      "to": "Logout"
    }
  ]
}

{
  "states": [
    "not authenticated state",
    "authenticated state"
  ],
  "transitions": [
    {
      "from": "not authenticated state",
      "event": "AUTHENTICATE",
      "action": "OK - authenticate completed, now in authenticated state",
      "to": "authenticated state"
    },
    {
      "from": "not authenticated state",
      "event": "LOGIN",
      "action": "OK - login completed, now in authenticated state",
      "to": "authenticated state"
    },
    {
      "from": "not authenticated state",
      "event": "STARTTLS",
      "action": "OK - starttls completed, begin TLS negotiation",
      "to": "not authenticated state"
    }
  ]
}

{
  "states": [
    "Authenticated State",
    "Selected State"
  ],
  "transitions": [
    {
      "from": "Authenticated State",
      "event": "ENABLE",
      "action": "OK - Relevant capabilities enabled; BAD - No arguments, or syntax error in an argument; * ENABLED response",
      "to": "Authenticated State"
    },
    {
      "from": "Authenticated State",
      "event": "SELECT",
      "action": "select a mailbox for access and enter the selected state",
      "to": "Selected State"
    },
    {
      "from": "Authenticated State",
      "event": "EXAMINE",
      "action": "select a mailbox for access and enter the selected state",
      "to": "Selected State"
    }
  ]
}

{
  "states": [
    "authenticated state",
    "selected state"
  ],
  "transitions": [
    {
      "from": "authenticated state",
      "event": "SELECT",
      "action": "OK - select completed, now in selected state; REQUIRED untagged responses: FLAGS, EXISTS, LIST, PERMANENTFLAGS, UIDNEXT, UIDVALIDITY",
      "to": "selected state"
    },
    {
      "from": "authenticated state",
      "event": "SELECT",
      "action": "NO - select failure, now in authenticated state",
      "to": "authenticated state"
    },
    {
      "from": "selected state",
      "event": "SELECT",
      "action": "OK - select completed, now in selected state; untagged OK response with [CLOSED] response code; REQUIRED untagged responses: FLAGS, EXISTS, LIST, PERMANENTFLAGS, UIDNEXT, UIDVALIDITY",
      "to": "selected state"
    },
    {
      "from": "selected state",
      "event": "SELECT",
      "action": "NO - select failure, now in authenticated state",
      "to": "authenticated state"
    }
  ]
}

{
  "states": [
    "Authenticated State",
    "Selected State"
  ],
  "transitions": [
    {
      "from": "Authenticated State",
      "event": "EXAMINE",
      "action": "OK - examine completed, now in selected state",
      "to": "Selected State"
    },
    {
      "from": "Authenticated State",
      "event": "EXAMINE",
      "action": "NO - examine failure, now in authenticated state",
      "to": "Authenticated State"
    },
    {
      "from": "Authenticated State",
      "event": "EXAMINE",
      "action": "BAD - command unknown or arguments invalid",
      "to": "Authenticated State"
    }
  ]
}

{
  "states": [
    "Authenticated State"
  ],
  "transitions": [
    {
      "from": "Authenticated State",
      "event": "DELETE",
      "action": "OK - delete completed; NO - delete failure; BAD - command unknown or arguments invalid; OPTIONAL untagged response: LIST",
      "to": "Authenticated State"
    }
  ]
}

{
  "states": [
    "Authenticated State"
  ],
  "transitions": [
    {
      "from": "Authenticated State",
      "event": "RENAME",
      "action": "OK - rename completed; NO - rename failure: can't rename mailbox with that name, can't rename to mailbox with that name; BAD - command unknown or arguments invalid; OPTIONAL untagged response: LIST",
      "to": "Authenticated State"
    }
  ]
}

{
  "states": [
    "Authenticated"
  ],
  "transitions": [
    {
      "from": "Authenticated",
      "event": "UNSUBSCRIBE",
      "action": "OK - unsubscribe completed\nNO - unsubscribe failure: can't unsubscribe that name\nBAD - command unknown or arguments invalid",
      "to": "Authenticated"
    }
  ]
}

{
  "states": [
    "IDLE",
    "Command Processing"
  ],
  "transitions": [
    {
      "from": "Command Processing",
      "event": "IDLE",
      "action": "server requests a response to the IDLE command using the continuation ('+') response",
      "to": "IDLE"
    },
    {
      "from": "IDLE",
      "event": "DONE",
      "action": "server ... MUST immediately send the tagged response to the IDLE command",
      "to": "Command Processing"
    }
  ]
}

{
  "states": [
